const raw = $input.first()?.json?.choices?.[0]?.message?.content || "{}";
let parsed = {};
try { parsed = JSON.parse(raw); } catch { parsed = { priority: "medium", summary: raw.slice(0, 400), nextAction: "review", messageDraft: raw }; }
return [{ json: { ...parsed, processedAt: new Date().toISOString() } }];

// Dead-letter error handler: log failure cleanly without crashing cron
